INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (36, 8, 'How do I start selling tickets?', 'Create an account, add your event details and flyer, set your ticket types and publish. Your event gets its own page and a link you can share.', 1, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (37, 8, 'What does TICA cost?', 'Creating an account and running free events costs nothing. Paid tickets carry a {fee} booking fee on each ticket''s price. You choose whether buyers pay it on top or it''s included in your price. Buyers always see the full total before they pay.', 2, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (38, 8, 'How do attendees get their tickets?', 'Tickets appear right after payment is confirmed and are sent to the buyer''s email. If a buyer adds a friend''s email, that ticket goes to the friend.', 3, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (39, 8, 'Which payment options can buyers use?', 'Payments go through Paystack or Monnify, which both support card, bank transfer and USSD.', 4, '2026-11-11 11:03:04', '2026-11-11 14:39:55') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (40, 8, 'I can''t find my ticket. What should I do?', 'Check your spam folder first. If it isn''t there, email tickets@tica.ng with your order number and we''ll resend it.', 5, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (41, 8, 'How do I get my money as an organiser?', 'Your sales are released 3 working days after your event ends. We send them to your verified bank account automatically, or you can withdraw whenever you like. Withdrawals usually arrive within minutes.', 6, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
INSERT INTO "faqs" ("id", "language_id", "question", "answer", "serial_number", "created_at", "updated_at") VALUES (42, 8, 'What if an event is cancelled?', 'You get a full refund, booking fee included, without needing to ask. It usually reaches you within 7 to 10 working days. See our <a href="/policies/refunds">refund policy</a> for the details.', 7, '2026-11-11 11:03:04', '2026-11-11 11:03:04') ON CONFLICT DO NOTHING;
