INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (4, 'verify_email', 'Verify Your Email Address', '<p>Hi <b>{username}</b>,</p><p>We just need to verify your email address before you can access to your dashboard.</p><p>Verify your email address, {verification_link}.</p><p>Thank you.<br />{website_title}</p><p><br /></p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (5, 'reset_password', 'Recover Password of Your Account', '<p>Hi {customer_name},</p><p>We have received a request to reset your password. If you did not make the request, just ignore this email. Otherwise, you can reset your password using this below link.</p><p>{password_reset_link}</p><p>Thanks,<br>{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (9, 'event_booking', 'Event Confirmation', '<p>Hi <span style="font-weight:600;">{customer_name}</span>,</p><p>You have successfully enrol in the following event.</p><p>Booking Id: #{order_id}<br />Event: {title} </p><p>Also, we have attached an invoice in this mail.</p><p>Best regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (10, 'event_booking_approved', 'Approval of Event Booking', '<p>Hi <span style="font-weight:600;">{customer_name}</span>,</p><p>Your payment is completed, and we have approved your booking for the following evnent.</p><p>Booking Id: #{order_id}<br /></p><p>Event : {title}</p><p>Also, we have attached an invoice in this mail.</p><p>Best regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (11, 'event_booking_rejected', 'Rejection of Event Booking', '<p>Hi <span style="font-weight:600;">{customer_name}</span>,</p><p>Your payment is not completed, thus we have rejected your Booking for the following Event.</p><p>Booking Id: #{order_id}<br /></p><p>Event : {title}</p><p>For further information, please do not hesitate to contact us.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (12, 'product_order', 'Order Confirmation', '<p>Hi <span style="font-weight:600;">{customer_name}</span>,</p><p>Your Order  has been  successfully Placed.</p><p>Order Id: #{order_id}<br /></p><p>Also, we have attached an invoice in this mail.</p><p>Best regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (13, 'withdraw_approve', 'Confirmation of Withdraw Approve', '<p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;">Hi {organizer_username},</p><p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;">This email confirms that your withdrawal request  {withdraw_id} is approved. </p><p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;">Your current balance is {current_balance}, withdraw amount {withdraw_amount}, charge : {charge},payable amount {payable_amount}</p><p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;">withdraw method : {withdraw_method}. The transaction id is {transaction_id}.</p><p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;"><br /></p><p style="font-family:Lato, sans-serif;font-size:14px;line-height:1.82;color:rgb(0,0,0);font-style:normal;font-weight:400;text-align:left;">Best Regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (14, 'withdraw_rejected', 'Withdraw Request Rejected', '<p>Hi {organizer_username},</p><p>This email confirms that your withdrawal request  {withdraw_id} is rejected and the balance added to your account. </p><p>Your current balance is {current_balance}</p><p><br /></p><p>Best Regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (15, 'balance_add', 'Balance Add', '<p>Hi {username}</p><p>{amount} added to your account.</p><p>Your current balance is {current_balance}. </p><p>The transaction id is {transaction_id}.<br /></p><p><br /></p><p>Best Regards.<br />{website_title}<br /></p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (16, 'balance_subtract', 'Balance Subtract', '<p>Hi {username}</p><p>{amount} subtract from your account.</p><p>Your current balance is {current_balance}.</p><p>The transaction id is {transaction_id}.<br /></p><p><br /></p><p>Best Regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
INSERT INTO "mail_templates" ("id", "mail_type", "mail_subject", "mail_body") VALUES (17, 'product_shipping', 'Product Shipping Status', '<p>Hi <span style="font-weight:600;">{customer_name}</span>,</p><p>Your order shipping status is {status}.</p><p>Order Id: #{order_id}</p><p>Best regards.<br />{website_title}</p>') ON CONFLICT DO NOTHING;
